CREATE TABLE IF NOT EXISTS gap (id INT AUTO_INCREMENT PRIMARY KEY, ticker VARCHAR(12) NOT NULL, `date` DATE NOT NULL, side VARCHAR(10) NOT NULL, quantity DECIMAL(18, 6) NOT NULL, unit_price DECIMAL(18, 6) NULL, status VARCHAR(20) NOT NULL, trade_watermark INT NOT NULL DEFAULT 0, action_watermark INT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL);
